  { id: 'other', tenant: 'a', owner: 'x', deleted: false, archived: false },
  { id: 'gone', tenant: 'a', owner: 'ed', deleted: true, archived: false },
  { id: 'foreign', tenant: 'b', owner: 'ed', deleted: false, archived: false },
  { id: 'done', tenant: 'a', owner: 'x', deleted: false, archived: true },
];
const admin = { tenant: 'a', user: 'ad', role: 'admin' };
const editor = { tenant: 'a', user: 'ed', role: 'editor' };
const viewer = { tenant: 'a', user: 'ed', role: 'viewer' };
function fails(actor, id, re) {
  const repo = new DocumentRepository(docs()); const before = JSON.stringify(repo.documents);
  assert.throws(() => new DocumentService(repo).archive(actor, id), re);
  assert.equal(JSON.stringify(repo.documents), before); assert.deepEqual(repo.audit, []);
}
for (const actor of [admin, editor, viewer]) for (const id of ['missing', 'gone', 'foreign']) fails(actor, id, /^Error: not found$/);
fails(editor, 'other', /^Error: forbidden$/);
fails(editor, 'done', /^Error: forbidden$/);
for (const id of ['own', 'other', 'done']) fails(viewer, id, /^Error: forbidden$/);
{ const repo = new DocumentRepository(docs()); const s = new DocumentService(repo);
  s.archive(editor, 'own'); s.archive(editor, 'own');
  assert.equal(repo.find('own').archived, true); assert.deepEqual(repo.audit, [{ actor: 'ed', document: 'own' }]); }
{ const repo = new DocumentRepository(docs()); const s = new DocumentService(repo);
  s.archive(admin, 'other'); s.archive(admin, 'done');
  assert.deepEqual(repo.audit, [{ actor: 'ad', document: 'other' }]); assert.equal(repo.find('done').archived, true); }
console.log('authorization checks passed');
